class Root {
  final int a;
  final B b;

  const Root({
    required this.a,
    required this.b,
  });

  factory Root.fromJson(Map<String, dynamic> json) => Root(
    a: json['a'] as int,
    b: B.fromJson(json['b'] as Map<String, dynamic>),
  );

  Map<String, dynamic> toJson() => {
    'a': a,
    'b': b.toJson(),
  };
}

class B {
  final dynamic c;

  const B({
    this.c,
  });

  factory B.fromJson(Map<String, dynamic> json) => B(
    c: json['c'],
  );

  Map<String, dynamic> toJson() => {
    'c': c,
  };
}

